-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.133.0',
  '2026-11-16',
  'AI — папки можно разрешать из приложения, сессии добавлять по id',
  E'AI. Раньше папки, в которых агенту разрешено работать, задавались только на машине (переменная AI_AGENT_DIRS) и менялись правкой файла с рестартом сервиса. Теперь папку можно разрешить прямо на странице: шестерёнка машины → «Папки для задач» → путь → «Разрешить». Агент получает её сразу, без рестарта, и папка появляется в выборе для задач и расписаний. В списке видно, что пришло из конфига машины (пометка «агент», убрать можно только там), а что разрешено здесь (пометка «здесь», убирается крестиком). Перед добавлением агент проверяет, что папка существует, — опечатка не попадёт в список.\n\nСессии. Агент показывает 300 самых свежих сессий CLI из разрешённых папок, и сессии постарше в список не попадали — как и те, чья папка разрешена только что. Теперь в «Сессиях» есть «＋ Сессия по id»: вводите id (у Claude Code это имя файла в ~/.claude/projects/<папка>/, у Codex — хвост имени rollout-файла), «Найти» — и агент говорит, где эта сессия лежит, как называется и сколько в ней реплик. Если её папка не разрешена, тут же кнопка «Разрешить эту папку». Добавленная сессия остаётся на странице с пометкой «вручную»: её историю можно прочитать и в ней можно поставить новую задачу — агент продолжит с её контекстом. Сессии открываются теперь и когда агент не в сети: добавленные вручную видно всегда, содержимое подтянется при подключении.\n\nБезопасность не изменилась: агент работает только в папках белого списка, от вашего пользователя. Папки из приложения он проверяет так же, как свои, и может вообще их не принимать (AI_AGENT_REMOTE_DIRS=0) — конфиг машины остаётся сильнее приложения.',
  E'Миграция 0192: ai_machine_dirs (machine_id, path, UNIQUE (machine_id, path)) — папки, разрешённые из приложения; ai_session_refs (machine_id, tool, session_id, workdir, title, UNIQUE (machine_id, tool, session_id)) — ручные сессии; ai_machines.agent_version — версия из hello (страница по ней предупреждает, что агент старше 1.8.0 папки из приложения не примет).\n\nДва списка папок не смешиваются. ai_machines.dirs приходит в hello и живёт в конфиге агента, ai_machine_dirs правится на странице. Полный список собирает aiHandlers.allowedAIDirs — по нему проверяются workdir задачи и расписания (workdirAllowed без изменений). Агент узнаёт о папках из приложения кадром dirs: сервер шлёт полный список при подключении (OnConnect → pushAIDirs, до deliverQueued) и после каждого добавления/удаления, поэтому рестарт агента не нужен, а удаление — это просто список без этой папки. Агент держит их в remoteDirs отдельно от dirs, прогоняет через ту же checkDir (абсолютный путь, не корень, не /proc|/sys|/dev, папка существует) и может отказаться принимать совсем — AI_AGENT_REMOTE_DIRS=0. dirAllowed проверяет оба списка, то есть агентский гейт остался на месте, но сервер теперь может его расширять: это осознанная уступка удобству, записана в DOCS.\n\nПеред добавлением папки сервер делает sync-вызов dir_check (15 с): агент отвечает {ok, error, branch} — существование папки и ветка git, если это репозиторий. Старый агент на dir_check не отвечает вовсе, вызов отваливается по таймауту, и папка добавляется без проверки (поэтому в UI предупреждение по agent_version).\n\nСессии по id. Индекс агента ограничен 300 свежими файлами, и readSession искал сессию ПО ЭТОМУ ЖЕ урезанному списку — то есть сессию из хвоста нельзя было прочитать даже зная id. Теперь sessionByID ищет файл напрямую (claude: ~/.claude/projects/*/<id>.jsonl, codex: */rollout-*<id>.jsonl; id проверяется регуляркой ^[A-Za-z0-9._-]+$ — он уходит в glob и в --resume), берёт карточку из того же кэша и проверяет папку через dirAllowed. На этом же стоит новый op session_find: POST /ai/machines/{id}/find-session возвращает {found, allowed, meta, error} — карточку и флаг разрешённости папки, чтобы страница могла предложить разрешить именно её. Ручные сессии хранит сервер (GET/POST /ai/machines/{id}/refs, DELETE .../refs/{ref_id}); в списке модалки они идут сверху одним v-for с индексными (sessionRows), и если сессия есть и там и там, карточка берётся из индекса, а ссылка остаётся для удаления. Задача в ручной сессии — обычный POST /ai/tasks с session_id, то есть ничего нового: проверка папки одна и та же.\n\nПроверено локально на одноразовой базе со настоящим агентом (AI_AGENT_CLAUDE подменён заглушкой): папка из приложения доехала до агента без рестарта, несуществующая отбита dir_check, сессия в неразрешённой папке нашлась с allowed=false и своим путём, после разрешения папки прочиталась и приняла задачу, удаление папки вернуло отказ, ручная сессия выжила перезапуск агента.'
);
-- +goose StatementEnd

